"""Read-only model inspection plus explicit source-interpretation review controls."""
import json
from .semantic_reader import AXES
from .semantic_controls import SCRIPT


def page():
    helpers=SCRIPT
    return HTML.replace('__AXES__',json.dumps({k:list(v) for k,v in AXES.items()})).replace('__HELPERS__',helpers)


HTML=r'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Agere · Statement interpretation</title>
<style>:root{color-scheme:dark;font-family:ui-sans-serif,system-ui;background:#101b21;color:#e7f0ed}*{box-sizing:border-box}body{margin:0}main{max-width:1080px;margin:auto;padding:40px 24px}a{color:#a3ddcb}h1{font-size:44px;letter-spacing:-1.5px;font-weight:500;margin:28px 0 18px}h2,h3{font-weight:500}p{line-height:1.6}.pill{color:#9fd2c2;font:12px ui-monospace,monospace;letter-spacing:2px}.meta{color:#9fb4b6;font-size:13px}.missing{color:#d9c9a8;font-size:13px}.source,article{border:1px solid #36505a;background:#15272e;border-radius:12px;padding:20px;margin:18px 0}.source .source{background:#102127}blockquote{white-space:pre-wrap;border-left:2px solid #9dd3c0;margin:20px 0;padding:10px 20px;line-height:1.7}button,select,input,textarea{font:inherit;background:#172d35;color:#e6f1ec;border:1px solid #52716f;border-radius:7px;padding:10px;min-height:42px;margin:5px 8px 5px 0;max-width:100%}button{cursor:pointer}button:disabled{opacity:.5}label{display:inline-block;margin:5px}textarea{display:block;width:100%;height:85px}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px}summary{cursor:pointer;color:#b0dcce}.controls{display:flex;gap:8px;flex-wrap:wrap}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:12px}.comparison{padding:14px;background:#0c1d24;border-radius:8px}.comparison strong{display:block;color:#b5e4d4}.empty{border:1px dashed #466061;padding:25px}.rowtitle{display:flex;flex-wrap:wrap;gap:12px;align-items:center}</style>
<main><nav><a href="/stack">← Stack workbench</a> · <a href="/programs">Program workspace</a> · <a href="/learn">Source learning queue</a></nav><p class="pill">AGERE / SOURCE MEANING / SYNTHETIC WORKSPACE</p><h1>Read the meaning.<br>Keep the evidence.</h1><p>A dose increase can be declined while the prescription continues. A referral can exist without a completed visit. Inspect how each reader separates the proposition, its time, and its relationship to care.</p><p class="missing">Model outputs are proposals. Reviewing a source interpretation does not verify current clinical state. Local reviewer identity is self-reported; no treatment or outreach runs here.</p>
<section aria-label="Local source interpretation training"><h2>Teach the inexpensive layer.</h2><p>Fit small classifiers to read the proposition, time and care relationship. Calibrate on separate examples. Keep validation separate from fitting, and keep uncertain readings available for review.</p><button id="students">Inspect trained local readers</button><div id="student-results" aria-live="polite"></div></section>
<form id="filters" class="controls"><input id="patient-filter" placeholder="Patient ID (optional)" aria-label="Filter semantic readings by patient"><button>Load saved interpretations</button></form><p id="status" role="status" aria-live="polite"></p><div id="readings"></div><div class="controls"><button id="previous">Previous</button><button id="next">Next</button><button id="learning">Inspect reviewed training candidates</button><button id="learning-ready">Training readiness</button></div><div id="learning-results"></div></main>
<script>const SEMANTIC_AXES=__AXES__;const $=id=>document.getElementById(id);const N=(tag,text,cls)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e};function details(title,data){const e=N('details');e.append(N('summary',title),N('pre',JSON.stringify(data,null,2)));return e}
__HELPERS__
let offset=0;const limit=24;
$('students').onclick=async()=>{try{const r=await semanticFetch('/api/stack/semantic-students');const grid=N('div',undefined,'grid');for(const [key,m] of Object.entries(r.models)){const c=N('article');c.append(N('h3',m.kind==='lexical'?'Lexical classifier':'MiniLM + learned heads'),N('p',m.supervision.replaceAll('_',' ')+' · '+m.release.status.replaceAll('_',' '),'missing'),N('p',m.counts.train+' training · '+m.counts.calibration+' calibration · '+m.counts.validation+' validation examples'),N('p',(100*m.validation.exact_match).toFixed(1)+(m.score_reference==='unreviewed_machine_teacher'?'% agreement with an unreviewed machine teacher across all three axes':'% development exact match across all three axes')),N('p',m.validation.selected_rows+' validation examples clear the calibration-selected threshold. This does not grant clinical acceptance.','meta'));for(const reason of m.release.reasons)c.append(N('p',reason,'meta'));c.append(details('Calibration, per-axis results, missingness and release decision',m));grid.append(c)}if(!Object.keys(r.models).length)grid.append(N('p','No trained local readers attached.'));$('student-results').replaceChildren(grid,N('p','These are interpretation scores with the target passage supplied. They do not measure retrieval recall, healthcare knowledge or patient outcomes. Local inference uses no hosted tokens; local compute still has a cost.','meta'))}catch(e){$('student-results').textContent=String(e)}};
function comparisons(data){
 const section=N('section');section.setAttribute('aria-label','Readers on identical source passages');
 section.append(N('h2','Where the readers agree—and where they differ.'),N('p','The same source, marked occurrence, and question contract. Agreement does not verify a clinical fact; differences stay available for review.','meta'));
 for(const group of data.comparisons_in_page||[]){
  if(group.readings.length<2)continue;
  const card=N('article');card.append(N('h3',group.patient_id+' · '+group.concept),N('blockquote',group.target_quote));
  const grid=N('div',undefined,'grid');
  for(const reading of group.readings){const cell=N('div',undefined,'comparison');cell.append(N('strong',reading.provider));for(const [axis,value] of Object.entries(reading.labels))cell.append(N('p',axis+': '+value.replaceAll('_',' ')));grid.append(cell)}
  card.append(grid,N('p',group.disagreement_axes.length?'Different proposals for: '+group.disagreement_axes.join(', '):'Matching proposals on these axes. Review still required.','missing'));section.append(card);
 }
 return section;
}
async function load(){try{$('status').textContent='Loading saved source interpretations…';const d=await semanticFetch('/api/stack/semantic/list?patient='+encodeURIComponent($('patient-filter').value)+'&offset='+offset);$('readings').replaceChildren(comparisons(d));for(const row of d.rows){const article=N('article');article.append(N('h2',row.patient_id+' · '+row.concept),N('p',row.provider+' · '+row.review_status,'meta'),N('blockquote',row.target_quote),N('p',Object.entries(row.labels).map(([k,v])=>k+': '+v.replaceAll('_',' ')).join(' · ')));const inspect=N('button','Inspect context and review this reading');inspect.onclick=async()=>{inspect.disabled=true;try{const r=await semanticFetch('/api/stack/semantic?id='+row.id);renderSemantic(article,r);semanticControl(article,r.target);const b=N('button','Inspect patient prerequisites');b.onclick=async()=>{try{article.append(details('Source reviews and existing requirement bindings',await semanticFetch('/api/stack/semantic/prerequisites?patient='+encodeURIComponent(row.patient_id))))}catch(e){article.append(N('p',String(e)))}};article.append(b)}catch(e){article.append(N('p',String(e)));inspect.disabled=false}};article.append(inspect);$('readings').append(article)}$('status').textContent=d.total+' saved readings; this is a development review workspace, not a patient-prevalence sample.';if(!d.rows.length)$('readings').append(N('p','No saved interpretations match. In the stack workbench, inspect reconciled accounts and open “Refine individual source statements.”','empty'));$('previous').disabled=offset===0;$('next').disabled=offset+limit>=d.total}catch(e){$('status').textContent=String(e)}}
$('filters').onsubmit=e=>{e.preventDefault();offset=0;load()};$('previous').onclick=()=>{offset=Math.max(0,offset-limit);load()};$('next').onclick=()=>{offset+=limit;load()};$('learning').onclick=async()=>{try{$('learning-results').replaceChildren(details('Explicitly reviewed examples only; no weights trained automatically',await semanticFetch('/api/stack/semantic/learning')))}catch(e){$('status').textContent=String(e)}};$('learning-ready').onclick=async()=>{try{const r=await semanticFetch('/api/stack/learning-readiness');const a=N('article');a.append(N('h2','Teach reusable healthcare skills'),N('p',r.saved_current_reader_results+' saved current reader outputs · '+r.distinct_reviewed_occurrences+' distinct source-reviewed examples'),N('p','Train source interpretation and question-planning skills. Keep changing clinical guidance, payer rules and financial calculations in versioned knowledge and code.'));for(const item of r.requires)a.append(N('p',item));a.append(details('Task labels and current supervision',r));$('learning-results').replaceChildren(a)}catch(e){$('status').textContent=String(e)}};load();</script></html>'''
